-- Camera/ShoulderCam.lua
L["Toggle Shoulder Cam"] = "Вкл./выкл. Камеру через плечо"
L["Moves the camera over your shoulder, using one of Blizzard's experimental camera settings."] = "Переносит камеру за плечо, используя одну из экспериментальных настроек камеры Blizzard."
L["Why the Shoulder Cam pauses while the gamepad UI is on."] = "Почему Камера через плечо на паузе, пока включен интерфейс геймпада."
L["Puts the camera over your left shoulder instead of your right."] = "Ставит камеру за левое плечо вместо правого."
L["How far from the middle of the screen you sit."] = "Насколько далеко от центра экрана вы находитесь."
L["Spot zoomed out"] = "Место при отдалении"
L["Zoomed out at"] = "Отдаление с"
L["How long the camera takes to swap to your other shoulder."] = "Сколько времени камера переходит на другое плечо."
L["How long the camera takes to go back over your shoulder after you stop targeting yourself."] = "Сколько времени камера возвращается за плечо после того, как вы перестали выбирать себя целью."
L["How long the camera takes to move behind you when the Shoulder Cam pauses, and back."] = "Сколько времени камера уходит вам за спину, когда Камера через плечо встает на паузу, и обратно."
L["The camera turns toward the NPC you talk to while their window is open."] = "Камера поворачивается к НИП, с которым вы говорите, пока открыто его окно."
L["Where the camera turns toward who you talk to."] = "Где камера поворачивается к собеседнику."
L["Escape clears your target and closes an NPC's window in one press."] = "Escape снимает цель и закрывает окно НИП одним нажатием."
L["Multi Quest fix"] = "Исправление нескольких заданий"
L["Dev test: at a quest giver with more quests, Accept clears your target first."] = "Тест разработчика: у персонажа с несколькими заданиями «Принять» сначала снимает цель."
L["How long the camera takes to glide back over your shoulder after you close the window."] = "Сколько времени камера плавно возвращается за плечо после закрытия окна."
L["Turns to your target everywhere, in fights too."] = "Поворачивается к цели везде, в бою тоже."
L["The camera turns slowly toward the enemy you target."] = "Камера медленно поворачивается к выбранному врагу."
L["Where the camera turns toward your target."] = "Где камера поворачивается к цели."
L["How long the turn toward your target takes."] = "Сколько длится поворот к цели."
L["Enemy turn back takes"] = "Возврат от врага за"
L["How long the camera takes to glide back after you clear your target."] = "Сколько времени камера плавно возвращается после снятия цели."
L["Glide back when you clear your target"] = "Плавный возврат при снятии цели"
L["Glides back instead of snapping when you clear your target, briefly using soft enemy targeting."] = "Плавно возвращается, а не рывком, когда вы снимаете цель, ненадолго используя мягкий выбор вражеской цели."
L["The ticked frames slide over to where you are on the screen."] = "Отмеченные рамки сдвигаются туда, где вы на экране."
L["Your cast bar and Personal Resource Display slide along as the camera turns to your target."] = "Полоса заклинаний и личная полоса ресурса сдвигаются, когда камера поворачивается к цели."
L["Slides with you."] = "Сдвигается вместе с вами."
L["Loss of control"] = "Потеря контроля"
L["Floating combat text"] = "Всплывающий текст боя"
L["Raises or lowers all the ticked frames while the camera is over your shoulder."] = "Поднимает или опускает все отмеченные рамки, пока камера за плечом."
L["How far the frames slide; adjust it if they land short of you or past you."] = "Насколько сдвигаются рамки; поправьте, если они не доходят до вас или проходят дальше."
L["This frame's own height, added to Height (all)."] = "Собственная высота этой рамки, добавляется к «Высоте (все)»."
L["Flight paths and their fly-bys."] = "Маршруты полетов и их облеты."

