-- Atmosphere/LowHealth.lua
L["How the low-health screen edges look."] = "Как выглядят края экрана при низком здоровье."
L["Turns this page's look settings on or off."] = "Включает или выключает настройки вида на этой странице."
L["Shows your health falling in the preview and on screen."] = "Показывает падение здоровья в предпросмотре и на экране."
L["The look of the edges; Auto picks one for your class and spec."] = "Вид краев; «Авто» выбирает по вашему классу и специализации."
L["Undoes your changes to this theme."] = "Отменяет ваши изменения этой темы."
L["Gives you this theme as text to share."] = "Дает эту тему в виде текста, чтобы поделиться."
L["Makes a blank theme of your own."] = "Создает вашу пустую тему."
L["Sound:"] = "Звук:"
L["The sound that plays as your health runs low."] = "Звук, который играет при низком здоровье."
L["Ambient volume"] = "Громкость окружения"
L["How loud the sound plays compared to your ambient volume."] = "Насколько громко играет звук относительно громкости окружения."
L["How strong the whole effect is."] = "Сила всего эффекта."
L["How far in from the edges the whole effect comes."] = "Насколько далеко от краев заходит весь эффект."
L["How bright the art's colors are."] = "Яркость цветов изображения."
L["Black at 0%, the theme's color at 100%."] = "Черный при 0%, цвет темы при 100%."
L["The edges flash when a big hit lands."] = "Края вспыхивают при сильном ударе."
L["Flash darkness"] = "Темнота вспышки"
L["How much darker the edges get in a flash, on top of Darkness."] = "Насколько темнее становятся края при вспышке, сверх «Темноты»."
L["Flash color"] = "Цвет вспышки"
L["How much a flash tints the edges."] = "Насколько вспышка окрашивает края."
L["Flash fade"] = "Затухание вспышки"
L["Seconds a flash takes to fade."] = "Сколько секунд гаснет вспышка."
L["How far in it comes from the left and right sides."] = "Насколько далеко он заходит с левой и правой сторон."
L["The sparks that float over the edges."] = "Искры, парящие над краями."
L["Wisps of heat rise from the bottom of the screen as you weaken."] = "Струйки жара поднимаются снизу экрана, когда вы слабеете."
L["A swirl that turns over the screen as you weaken."] = "Вихрь, кружащий по экрану, когда вы слабеете."
L["The kind of swirl."] = "Тип вихря."
L["How fast the swirl turns; below 0 turns the other way."] = "Как быстро кружится вихрь; меньше 0 — в другую сторону."
L["The game's own screen effects closing in at the edges."] = "Собственные экранные эффекты игры, наползающие с краев."
L["A wave of the game's art creeps in on each heartbeat."] = "С каждым ударом сердца наползает волна изображения игры."
L["Which of the game's effects shows."] = "Какой из эффектов игры показывается."
L["What shape cuts the effect to the screen's edges."] = "Какой формой эффект обрезается по краям экрана."
L["Tint the effect to your theme or keep its own colors."] = "Окрасить эффект в цвет темы или оставить его цвета."
L["A second game effect over the first."] = "Второй эффект игры поверх первого."
L["The game's effects slide slowly under their edge."] = "Эффекты игры медленно скользят под своим краем."
L["One of the game's full-screen effects closing in as you weaken."] = "Один из полноэкранных эффектов игры, наползающий, когда вы слабеете."
L["Turns Vitals Vision on or off."] = "Включает или выключает Vitals Vision."
L["The screen's edges close in as your health drops."] = "Края экрана сжимаются по мере падения здоровья."
L["How strong the edges are out of a fight."] = "Насколько сильны края вне боя."
L["Ramp up"] = "Нарастание"
L["Higher makes the edges close in slowly at first, then faster."] = "Чем выше, тем медленнее края сжимаются вначале и быстрее потом."
L["Replace game's low health flash setting"] = "Заменить вспышку игры при низком здоровье"
L["When the game's Do Not Flash Screen at Low Health setting is ticked, the edges don't show."] = "Если в игре отмечен параметр «Не мигать экраном при низком здоровье», края не показываются."
L["Game setting: |cffff8000no flash|r (edges off while followed)"] = "Настройка игры: |cffff8000без вспышки|r (края выключены, пока ей следуют)"
L["Game setting: |cff00ff00flash on|r"] = "Настройка игры: |cff00ff00вспышка вкл.|r"
L["How fast the edges close in when your health drops."] = "Как быстро края сжимаются при падении здоровья."
L["How fast the edges lift when you're healed."] = "Как быстро края отступают, когда вас исцеляют."
L["Smaller hits that add up to this much of your health count as a big one."] = "Мелкие удары, которые в сумме дают такую долю здоровья, считаются сильным ударом."

