L["Casts count too when a rule uses Casting."] = "Заклинания тоже учитываются, когда правило использует «Произнесение»."
L["As soon as a fight ends"] = "Сразу после боя"
L["How long after a fight before CineMode comes back."] = "Через сколько после боя вернется CineMode."
L["Ends the Calm Timer early once your health and power are back to full."] = "Досрочно завершает таймер затишья, когда здоровье и ресурс полностью восстановятся."
L["With a pet out, its health must be full too."] = "Если питомец призван, его здоровье тоже должно быть полным."
L["Exit CineMode while an NPC window, like a quest giver or vendor, is open."] = "Выходить из CineMode, пока открыто окно НИП, например задания или торговца."
L["Exit CineMode while a game window, like your bags or the map, is open."] = "Выходить из CineMode, пока открыто окно игры, например сумки или карта."
L["Picking up an item or spell brings the UI back until you put it down."] = "Если взять предмет или заклинание на курсор, интерфейс возвращается, пока вы его не положите."
L["How long things must stay calm before CineMode comes back."] = "Сколько должно быть спокойно, прежде чем CineMode вернется."
L["Casting at an enemy out of combat brings up your combat frames."] = "Заклинание по врагу вне боя показывает ваши боевые рамки."
L["Being in combat brings the UI back."] = "Бой возвращает интерфейс."
L["In the open world"] = "В открытом мире"
L["Anywhere outside cities, dungeons and raids."] = "Везде, кроме городов, подземелий и рейдов."
L["Capital cities, including Dalaran."] = "Столицы, включая Даларан."
L["While you're flagged for PvP out in the world."] = "Пока вы в режиме PvP в открытом мире."
L["In battlegrounds"] = "На полях боя"
L["Battlegrounds and arenas."] = "Поля боя и арены."
L["Back after stopping"] = "Возврат после остановки"
L["CineMode comes back once you've stood still this long."] = "CineMode вернется, когда вы простоите на месте столько времени."
L["Back after moving"] = "Возврат после движения"
L["CineMode comes back once you've kept moving this long."] = "CineMode вернется, когда вы будете двигаться столько времени."
L["Allow outside CineMode"] = "Разрешить вне CineMode"
L["CineMode hides your buffs and debuffs: pick what brings them back."] = "CineMode скрывает баффы и дебаффы: выберите, что их возвращает."
L["Gaining or refreshing a buff briefly shows your buffs and debuffs."] = "Получение или обновление баффа ненадолго показывает баффы и дебаффы."
L["Lets this page bring your hidden buffs and debuffs back in CineMode."] = "Позволяет этой странице возвращать скрытые баффы и дебаффы в CineMode."
L["What brings your hidden buffs and debuffs up for a while."] = "Что ненадолго показывает скрытые баффы и дебаффы."
L["Buffs you or your pet cast on yourself don't bring them up."] = "Баффы, наложенные вами или питомцем на себя, их не показывают."
L["Not while skyriding"] = "Не в высшем пилотаже"
L["No buff brings them up while you're on a skyriding mount."] = "Никакой бафф их не показывает, пока вы на транспорте высшего пилотажа."
L["Only the buff you gained or refreshed shows."] = "Показывается только полученный или обновленный бафф."
L["Keep ones lasting less than up until they run out"] = "Держать короткие до окончания"
L["A short buff stays up for as long as it lasts."] = "Короткий бафф остается на экране, пока действует."
L["Gaining or refreshing a debuff briefly shows your debuffs."] = "Получение или обновление дебаффа ненадолго показывает дебаффы."
L["Only within the Calm Timer after a fight."] = "Только в таймере затишья после боя."
L["Keeps them up while you have any debuff."] = "Держит их, пока на вас есть дебафф."
L["Debuffs that last longer than this don't bring them up."] = "Дебаффы длиннее этого их не показывают."
L["Override Default Buff Reveal Time"] = "Свое время показа баффов"
L["How long a new buff keeps the buffs up."] = "Сколько новый бафф держит баффы на экране."
L["Override Default Debuff Reveal Time"] = "Свое время показа дебаффов"
L["How long a new debuff keeps the buffs up."] = "Сколько новый дебафф держит баффы на экране."
L["Gaining this doesn't bring your buffs up; type a spell ID or name."] = "Получение этого не показывает баффы; введите ID или название заклинания."
L["Keeps drifting to new random distances after the first pull-back."] = "После первого отдаления продолжает плавно менять расстояние случайным образом."
L["How much closer than your own zoom the random zoom may come."] = "Насколько ближе вашего зума может подойти случайный зум."
L["How much of each zoom is spent speeding up and slowing down."] = "Какая часть каждого зума уходит на разгон и торможение."
L["Each pause varies at random by up to this much."] = "Каждая пауза случайно меняется не более чем на эту величину."
L["Raises the game's max camera distance while pulled back."] = "Увеличивает максимальное расстояние камеры в игре при отдалении."
L["Lets the cameras start as the rows below say."] = "Позволяет камерам запускаться, как задано в строках ниже."
L["Top speed in the middle of a sweep."] = "Максимальная скорость в середине облета."
L["Each new angle is at least this many degrees from the last."] = "Каждый новый угол отличается от прежнего не меньше чем на столько градусов."
L["How far the camera may sway to either side."] = "Насколько камера может отклоняться в каждую сторону."
L["Each move also tilts the camera to a random angle between these limits."] = "Каждое движение также наклоняет камеру на случайный угол в этих пределах."
L["The camera never tilts more than this far below where it started."] = "Камера никогда не наклоняется ниже начальной точки больше чем на это значение."
L["How much of each move is spent speeding up and slowing down."] = "Какая часть каждого движения уходит на разгон и торможение."
L["How long the camera rests between sweeps."] = "Сколько камера отдыхает между облетами."
L["Puts this camera's settings back to your profile's values."] = "Возвращает настройки этой камеры к значениям профиля."
L["Runs this camera for 30 seconds where you stand."] = "Запускает эту камеру на 30 секунд там, где вы стоите."
L["The camera slowly pulls back, then drifts in and out."] = "Камера медленно отдаляется, затем плавно приближается и отдаляется."
L["After you move the camera yourself, it waits this long before carrying on."] = "Если вы сами сдвинули камеру, она ждет столько, прежде чем продолжить."
L["Doing the emote or pressing the sit key."] = "Эмоция или нажатие клавиши «сесть»."
L["Clicking Sit, Kneel or Lie down on the campfire card, or its fire button (Emote Vision)."] = "Нажатие «Сесть», «Преклонить колено» или «Лечь» на карточке костра или ее кнопки огня (Emote Vision)."
L["Doing the emote, until you move or jump."] = "Эмоция, пока вы не двинетесь или не прыгнете."
L["Right-clicking a seat to sit on it."] = "ПКМ по сиденью, чтобы сесть."
L["Unsheathing your weapon with your Sheathe key out of combat."] = "Доставание оружия клавишей оружия вне боя."
L["Casting your Hearthstone."] = "Использование камня возвращения."
L["Casting a teleport spell."] = "Заклинание телепортации."
L["Logging out where the game counts down first."] = "Выход из игры там, где игра сначала ведет отсчет."
L["Doing the emote while standing still."] = "Эмоция, пока вы стоите на месте."
L["Casting Fishing, until you move or jump."] = "Рыбная ловля, пока вы не двинетесь или не прыгнете."
L["Being flagged AFK."] = "Статус «Отошел» (АФК)."
L["Standing still for the time below with nothing else going on."] = "Стояние на месте в течение времени ниже, когда больше ничего не происходит."
L["Taking off on a flight path."] = "Взлет на маршруте полета."
L["Talking to a quest giver."] = "Разговор с тем, кто дает задание."
L["Talking to an NPC about a quest step."] = "Разговор с НИП об этапе задания."
L["On flight paths, the camera sways side to side with an occasional fly-by."] = "На маршрутах полетов камера покачивается из стороны в сторону и иногда облетает вас."
L["Your target's frames fade until you pick a new target or land."] = "Рамки цели скрываются, пока вы не выберете новую цель или не приземлитесь."
L["Sway from side to side"] = "Покачивание"
L["The camera sways from side to side around where it started."] = "Камера покачивается из стороны в сторону вокруг начальной точки."
L["Your character does /look as a fly-by starts, which players nearby see."] = "Ваш персонаж делает /look в начале облета, и это видят игроки рядом."
L["About one fly-by per this many seconds of flight."] = "Примерно один облет за столько секунд полета."
L["Turn round"] = "Разворот"
L["Turn back before landing"] = "Вернуться перед посадкой"
L["Before you land, the camera turns back to where it was at takeoff."] = "Перед посадкой камера возвращается туда, где была при взлете."
L["Turned back by"] = "Вернуться за"
L["How long before landing the camera has settled."] = "За сколько до посадки камера должна успокоиться."
L["When you stand still a while or go AFK, the camera slowly circles your character."] = "Когда вы долго стоите на месте или отходите, камера медленно облетает персонажа."
L["The camera sweeps around your character, pausing between sweeps."] = "Камера облетает персонажа с паузами между облетами."
L["While you auto-run, the camera follows along until you stop or steer."] = "Во время автобега камера следует за вами, пока вы не остановитесь или не повернете."
L["The camera eases out a little, then drifts in and out."] = "Камера немного отдаляется, затем плавно приближается и отдаляется."
L["When you rest, sit or dance, the camera slowly turns to face you and eases in."] = "Когда вы отдыхаете, сидите или танцуете, камера медленно поворачивается к вам лицом и приближается."
L["How far the camera comes down toward the ground as it turns."] = "Насколько камера опускается к земле при развороте."
L["The camera eases in close, then drifts a little in and out."] = "Камера плавно приближается, затем немного приближается и отдаляется."
L["The close-up distance the cozy camera zooms in to."] = "Расстояние крупного плана уютной камеры."
L["How much lower the camera sways, to look out across the view."] = "Насколько ниже покачивается камера, чтобы смотреть на пейзаж."
L["The camera eases out a little, then drifts slowly in and out."] = "Камера немного отдаляется, затем медленно приближается и отдаляется."
L["The camera sways a little from side to side."] = "Камера слегка покачивается из стороны в сторону."
L["How much lower the camera sways, to look out across the water."] = "Насколько ниже покачивается камера, чтобы смотреть на воду."
L["When you die, the camera slowly circles your body until you release or are revived."] = "Когда вы погибаете, камера медленно облетает тело, пока вы не покинете его или вас не воскресят."
L["If you die in a boss fight, the death camera waits for it to end."] = "Если вы погибли в бою с боссом, камера смерти ждет его окончания."
L["No death camera when you can come back yourself, like with a soulstone."] = "Без камеры смерти, если вы можете вернуться сами, например с камнем души."
L["Adds a button under the release popup to get your own view back."] = "Добавляет под окном выхода из тела кнопку, возвращающую ваш вид."
L["How far the camera pulls back while you're dead."] = "Насколько камера отдаляется, пока вы мертвы."
L["How far the camera rises to look down on your body."] = "Насколько камера поднимается, чтобы смотреть на тело сверху."
L["The groups ticked here stay up while the death camera hides your frames."] = "Отмеченные группы остаются, пока камера смерти скрывает рамки."
L["Music file IDs, separated by commas; one plays at random when you die."] = "ID музыкальных файлов через запятую; при смерти играет случайный."
L["The camera turns toward NPCs as they talk near you."] = "Камера поворачивается к НИП, когда они говорят рядом."
L["The fastest the camera swings toward a new speaker."] = "Предельная скорость поворота камеры к новому говорящему."
L["How far from the screen's center the speaker ends up."] = "Насколько далеко от центра экрана оказывается говорящий."
L["How far the camera drifts side to side once settled."] = "Насколько камера плывет из стороны в сторону, успокоившись."
L["The camera turns around to find speakers you can't see."] = "Камера разворачивается, чтобы найти невидимых говорящих."
L["Snaps to speakers, adds a tall letterbox with subtitles and fades the whole UI."] = "Резко переключается на говорящих, добавляет высокие полосы кадра с субтитрами и скрывает весь интерфейс."
L["How fast the camera zooms back out once the talking is over."] = "Как быстро камера отдаляется обратно после разговора."
L["The longest a zoom in or out can take."] = "Максимальная длительность приближения или отдаления."
L["How long no one must talk before the camera turns back."] = "Сколько должно быть тихо, прежде чем камера повернется обратно."
L["When you talk to a quest giver, the camera zooms in and looks past you at them."] = "Когда вы говорите с тем, кто дает задание, камера приближается и смотрит на него из-за вашего плеча."
L["Also zooms in for NPCs with nothing to say about quests."] = "Также приближается к НИП, которым нечего сказать о заданиях."
L["The camera stays put when a quest giver only has dailies or weeklies."] = "Камера не двигается, если у персонажа только ежедневные или еженедельные задания."
L["How far the camera turns to one side to look past you."] = "Насколько камера поворачивается в сторону, чтобы смотреть мимо вас."
L["How long the turn to the side takes."] = "Сколько длится поворот в сторону."
L["How fast the camera zooms back out once you walk away."] = "Как быстро камера отдаляется обратно, когда вы уходите."
L["How far the camera comes down toward eye level."] = "Насколько камера опускается к уровню глаз."
L["When you cast your Hearthstone or a teleport, the camera spins around you as it zooms in."] = "Когда вы используете камень возвращения или телепортацию, камера кружит вокруг вас, приближаясь."
L["The distance the zoom ends at as the cast finishes."] = "Расстояние, на котором зум заканчивается к концу заклинания."
L["Canceling"] = "Отмена"
L["If you cancel the cast, the camera turns back to where it was."] = "Если вы отмените заклинание, камера вернется на прежнее место."
L["Extra settings for cameras that aren't on the Scripts page yet."] = "Доп. настройки для камер, которых пока нет на странице «Сценарии»."
L["Mouse Turn"] = "Поворот мышью"
L["Keeps right-mouse turning smooth by capping and easing its speed."] = "Делает поворот правой кнопкой мыши плавным, ограничивая и сглаживая скорость."
L["Cap"] = "Предел"
L["Cap right-click turn speed"] = "Ограничить скорость поворота ПКМ"
L["Right-click turning never goes faster than the speed below."] = "Поворот ПКМ никогда не быстрее скорости ниже."
L["Top turn speed"] = "Макс. скорость поворота"
L["The fastest you can turn."] = "Самый быстрый возможный поворот."
L["Ease back over"] = "Плавный возврат за"
L["How long your own Mouse Look Speed takes to come back after you slow down."] = "Сколько возвращается ваша «Скорость обзора мышью» после замедления."
L["Ramp up right-click turn speed"] = "Разгонять поворот ПКМ"
L["Each right-click turn starts slow and builds up to your own speed."] = "Каждый поворот ПКМ начинается медленно и разгоняется до вашей скорости."
L["Start at"] = "Начать с"
L["%d%% of your speed"] = "%d%% вашей скорости"
L["How fast a turn starts, as a share of your own Mouse Look Speed."] = "С какой скорости начинается поворот, как доля вашей «Скорости обзора мышью»."
L["Up to full speed over"] = "До полной скорости за"
L["How long a turn takes to build up to full speed."] = "За сколько поворот разгоняется до полной скорости."
L["Slow looking up and down too"] = "Замедлять и обзор вверх-вниз"
L["Looking up and down slows by the same share as turning."] = "Обзор вверх-вниз замедляется на ту же долю, что и поворот."
L["Turns the whole Atmosphere hub on or off at once."] = "Включает или выключает весь раздел «Атмосфера» сразу."
L["How the game world looks in CineMode: vignette, inn glow, weather and depth of field."] = "Как выглядит игровой мир в CineMode: виньетка, свет в тавернах, погода и глубина резкости."
L["Pick where and when each effect shows in CineMode."] = "Выберите, где и когда каждый эффект показывается в CineMode."
L["Shows all the time in CineMode, fights included."] = "Показывается все время в CineMode, включая бои."
L["Rain, snow and sandstorms tint the scene, more strongly in heavier weather."] = "Дождь, снег и песчаные бури окрашивают сцену, тем сильнее, чем суровее погода."
L["Reduce view distance in bad weather"] = "Меньше дальность в непогоду"
L["Brings the view distance in during rain, snow or sandstorms, more the heavier it gets."] = "Уменьшает дальность обзора в дождь, снег или песчаную бурю, тем сильнее, чем суровее погода."
L["The game's graphics settings one by one, shared by every profile on this computer."] = "Настройки графики игры по отдельности, общие для всех профилей на этом компьютере."
L["Uses the settings below, or the game's own when turned off."] = "Использует настройки ниже, а если выключено — настройки игры."
L["World"] = "Мир"
L["Ground clutter, view distance, detail and shadows."] = "Растительность, дальность обзора, детализация и тени."
L["Sky and water"] = "Небо и вода"
L["Clouds, fog, reflections and ripples."] = "Облака, туман, отражения и рябь."
L["Effects"] = "Эффекты"
L["Particles, glow, blood and sharpening."] = "Частицы, свечение, кровь и резкость."
L["HDR"] = "HDR"
L["HDR output and brightness."] = "Вывод HDR и яркость."
L["Nameplate distance and zoom distance."] = "Дальность индикаторов и отдаления камеры."
L["How far away grass and flowers start thinning out."] = "На каком расстоянии трава и цветы начинают редеть."
L["How far the land is drawn in full; very demanding on frame rate."] = "Насколько далеко земля рисуется полностью; сильно влияет на частоту кадров."
L["How far away trees, rocks and other objects keep their full detail."] = "До какого расстояния деревья, камни и другие объекты сохраняют полную детализацию."
L["How far away small objects stay before they fade out."] = "До какого расстояния видны мелкие объекты."
L["How far away creatures and characters keep their full detail."] = "До какого расстояния существа и персонажи сохраняют полную детализацию."
L["How far away nameplates show, in yards."] = "На каком расстоянии видны индикаторы, в метрах."
L["How far out you can zoom the camera."] = "Насколько далеко можно отдалить камеру."
L["Higher gives sharper shadow edges, lower saves frame rate."] = "Выше — четче края теней, ниже — больше кадров в секунду."
L["Horizon distance"] = "Дальность горизонта"
L["How far the flat horizon past the land reaches."] = "Насколько далеко простирается плоский горизонт за землей."
L["Sky detail"] = "Детализация неба"
L["How detailed the clouds and sky are."] = "Детализация облаков и неба."
L["Volumetric fog"] = "Объемный туман"
L["Fog with depth in place of the usual distance fog."] = "Туман с глубиной вместо обычного дальнего тумана."
L["Water reflections"] = "Отражения в воде"
L["How much of the world water reflects."] = "Какую часть мира отражает вода."
L["Water ripples"] = "Рябь на воде"
L["How detailed the ripples on water are."] = "Детализация ряби на воде."
L["Particle density"] = "Плотность частиц"
L["How many particles spells and effects show."] = "Сколько частиц у заклинаний и эффектов."
L["Full-screen glow"] = "Полноэкранное свечение"
L["A soft glow around bright light."] = "Мягкое свечение вокруг яркого света."
L["Gray screen on death"] = "Серый экран при смерти"
L["The world turns gray while you're dead."] = "Мир становится серым, пока вы мертвы."
L["Blood and gore"] = "Кровь"
L["How much blood shows in fights, from none to the most."] = "Сколько крови видно в бою, от нисколько до максимума."
L["Always sharpen"] = "Всегда повышать резкость"
