L["Peak brightness"] = "Пиковая яркость"
L["Your monitor's peak brightness, in nits."] = "Пиковая яркость вашего монитора, в нитах."
L["HDR strength"] = "Сила HDR"
L["How strong HDR is; works with peak brightness only."] = "Сила HDR; работает только с пиковой яркостью."
L["Use reference brightness"] = "Опорная яркость"
L["Reference brightness"] = "Опорная яркость"
L["How bright white looks in HDR, in nits."] = "Насколько ярок белый в HDR, в нитах."
L["Sky and weather"] = "Небо и погода"
L["Water"] = "Вода"
L["Restart graphics"] = "Перезапустить графику"
L["Restarts the game's graphics without leaving the game; the screen goes black for a moment."] = "Перезапускает графику, не выходя из игры; экран ненадолго гаснет."
L["Sound and music during CineMode; your own sound settings come back afterward."] = "Звук и музыка в CineMode; ваши настройки звука затем возвращаются."
L["Plays music when a camera starts in CineMode and fades it out when the UI returns."] = "Включает музыку, когда в CineMode запускается камера, и приглушает ее, когда возвращается интерфейс."
L["Pick where and when music can play in CineMode."] = "Выберите, где и когда в CineMode может играть музыка."
L["After a camera starts music, no camera starts it again for this long."] = "После того как камера включила музыку, столько времени ни одна камера не включит ее снова."
L["Fades music out once you leave the camera modes and move on."] = "Приглушает музыку, когда вы выходите из режимов камеры и идете дальше."
L["Each row is a scene that plays its camera when one of its triggers happens."] = "Каждая строка — сцена, которая запускает свою камеру при срабатывании одного из ее триггеров."
L["Lets the scenes below play their cameras when their triggers happen."] = "Позволяет сценам ниже запускать камеры при срабатывании их триггеров."
L["Auto-running in walk mode."] = "Автобег в режиме шага."
L["Auto-running."] = "Автобег."
L["Dying, until you release or are resurrected."] = "Смерть, пока вы не покинете тело или вас не воскресят."
L["An NPC talking to you or your party; the camera swings toward whoever's talking."] = "НИП говорит с вами или вашей группой; камера поворачивается к говорящему."
L["Other NPCs talking near you, once you've stood still a while."] = "Другие НИП говорят рядом, когда вы немного постоите на месте."
L["Starts music as this camera starts; needs the Audio page on."] = "Включает музыку при запуске этой камеры; нужна включенная страница «Звук»."
L["Plays a song of its own while the death camera runs."] = "Играет свою мелодию, пока работает камера смерти."
L["Brings CineMode on while this camera runs, when Start in CineMode is off."] = "Включает CineMode, пока работает эта камера, когда «Запуск в CineMode» выключен."
L["Buff names or spell IDs, separated by commas."] = "Названия баффов или ID заклинаний через запятую."
L["Words in an object's name that mark it as a seat, separated by commas."] = "Слова в названии объекта, по которым узнается сиденье, через запятую."
L["How long you stand still before this row's camera starts."] = "Сколько нужно простоять на месте до запуска камеры этой строки."
L["How long the camera waits on a quest window before it starts."] = "Сколько камера ждет на окне задания перед запуском."
L["How long the camera waits on the window before it starts."] = "Сколько камера ждет на окне перед запуском."
L["How long you stand still before NPCs chatting nearby start this camera."] = "Сколько нужно простоять на месте, чтобы болтовня НИП рядом запустила эту камеру."
L["How long you keep going before this row's camera starts."] = "Сколько нужно продолжать движение до запуска камеры этой строки."
L["Whether this row's camera may start in or after a fight."] = "Может ли камера этой строки запускаться в бою или после него."
L["Where this row's camera may start."] = "Где может запускаться камера этой строки."
L["Pause cameras while a window is open"] = "Пауза камер при открытом окне"
L["Scenes pause while a window like the map or spellbook is open."] = "Сцены встают на паузу, пока открыто окно, например карта или книга заклинаний."
L["Lists the rows by camera name or by scene name."] = "Упорядочивает строки по названию камеры или сцены."
L["Make a scene of your own with its triggers, camera and end."] = "Создайте свою сцену с триггерами, камерой и завершением."
L["A scene of your own; open it to set its triggers and when it ends."] = "Ваша сцена; откройте ее, чтобы задать триггеры и завершение."
L["Copies this row just below, so you can give it another camera."] = "Копирует строку прямо под ней, чтобы задать ей другую камеру."
L["Deletes this scene so it starts no camera."] = "Удаляет эту сцену, чтобы она не запускала камеру."
L["Your own name for this row, shown on the grid."] = "Ваше название строки, показывается в таблице."
L["The camera this row starts."] = "Камера, которую запускает эта строка."
L["This row's camera may start anywhere."] = "Камера этой строки может запускаться где угодно."
L["Indoors, the camera modes zoom out and swing less so they don't hit walls."] = "В помещении режимы камеры меньше отдаляются и раскачиваются, чтобы не задевать стены."
L["How far past your own distance the slow zoom may pull back indoors."] = "Насколько дальше вашего расстояния медленный зум может отдаляться в помещении."
L["Stops the AFK camera sweeping around you indoors, where it can hit walls."] = "Отключает облет АФК-камеры в помещении, где она может задевать стены."
L["Shows it whenever its frame shows, hovered or not."] = "Показывает всякий раз, когда видна его рамка, с наведением или без."
L["Shows it the whole time, CineMode or not."] = "Показывает все время, в CineMode или нет."
L["CineMode hides everything: pick which frames show, and when."] = "CineMode скрывает все: выберите, какие рамки показывать и когда."
L["CineMode hides everything: tick which frames show, and when."] = "CineMode скрывает все: отметьте, какие рамки показывать и когда."
L["CineMode hides these frames, and shows them only when their rows say."] = "CineMode скрывает эти рамки и показывает их, только когда велят их строки."
L["CineMode hides the frames in this section, and shows them only when their rows say."] = "CineMode скрывает рамки этого раздела и показывает их, только когда велят их строки."
