L["These bubbles show everywhere, in fights and out."] = "Эти облачка видны везде, в бою и вне его."
L["Cinematic draws its own bubbles for speech whose game bubble you can't see."] = "Cinematic рисует свои облачка для речи, игровое облачко которой вам не видно."
L["Shows speech from someone off screen in a bubble low on the screen."] = "Показывает речь того, кто за пределами экрана, в облачке внизу экрана."
L["Opens the Chat Bubble Style page: how off-screen bubbles look and where they show."] = "Открывает страницу «Стиль облачков чата»: как выглядят и где показываются облачка за экраном."
L["Shows emotes in the off-screen bubbles too, instead of in chat."] = "Показывает эмоции тоже в облачках за экраном, а не в чате."
L["Moves bubbles at the very top of the screen down where you can read them."] = "Опускает облачка с самого верха экрана, чтобы их можно было прочитать."
L["Small helpers for getting around the world."] = "Небольшие помощники для путешествий по миру."
L["Turns all the Quality of Life helpers on or off."] = "Включает или выключает всех помощников «Удобства»."
L["Opens the character window when you drag gear out of your bags."] = "Открывает окно персонажа, когда вы вытаскиваете снаряжение из сумок."
L["Adds a button to view the talents of someone you inspect."] = "Добавляет кнопку просмотра талантов осматриваемого игрока."
L["Adds a talent calculator button to your talents window to plan a build."] = "Добавляет в окно талантов кнопку калькулятора для планирования билда."
L["Moves game windows away from the left edge so your character stays in view."] = "Отодвигает окна игры от левого края, чтобы персонаж оставался в кадре."
L["Lets you drag the game's windows to move them."] = "Позволяет перетаскивать окна игры."
L["Adds an icon to chat windows to copy their text."] = "Добавляет в окна чата значок для копирования текста."
L["Keep chat history"] = "Сохранять историю чата"
L["Chat windows bring back their last lines after a reload or login."] = "Окна чата восстанавливают последние строки после перезагрузки или входа."
L["Show the time on those lines"] = "Время на этих строках"
L["Puts the time at the start of brought-back lines."] = "Ставит время в начале восстановленных строк."
L["Show XP left to level"] = "Опыт до уровня"
L["Shows how much XP you still need for the next level."] = "Показывает, сколько опыта осталось до следующего уровня."
L["The camera zooms to the distance below when you log in or reload."] = "Камера переходит на расстояние ниже при входе или перезагрузке."
L["The camera distance to start at."] = "Начальное расстояние камеры."
L["A button at the top of the screen that reloads the UI in one click."] = "Кнопка вверху экрана, перезагружающая интерфейс одним щелчком."
L["Reopens the windows you had open after a reload."] = "Снова открывает окна, открытые до перезагрузки."
L["Hides floating damage and healing numbers in CineMode out of combat."] = "Скрывает всплывающие числа урона и исцеления в CineMode вне боя."
L["Hides the red error text while you're fighting."] = "Скрывает красный текст ошибок в бою."
L["Hides the red error text while you're out of combat."] = "Скрывает красный текст ошибок вне боя."
L["Turns the Hunter helpers on or off."] = "Включает или выключает помощников охотника."
L["Right-clicking an enemy uses Auto Shot when it's far enough away."] = "ПКМ по врагу использует «Автоматическую стрельбу», если он достаточно далеко."
L["Moves the smallest ammo stack first after Clean Up Bags, so it's shot first."] = "После сортировки сумок ставит самую маленькую пачку боеприпасов первой, чтобы ее расстреляли раньше."
L["Adds a Fill button at vendors that fills your quiver with ammo."] = "Добавляет у торговцев кнопку «Заполнить», наполняющую колчан боеприпасами."
