L["Damaged gear"] = "Поврежденное снаряжение"
L["Shows the damaged gear figure while your gear needs repair."] = "Показывает фигурку прочности, пока снаряжению нужен ремонт."
L["Hides the damaged gear figure during camera modes."] = "Скрывает фигурку прочности в режимах камеры."
L["Turns everything on this tab on or off."] = "Включает или выключает все на этой вкладке."
L["Every Vision at a glance; click a card to open it."] = "Все Visions с первого взгляда; щелкните по карточке, чтобы открыть."
L["Turns all Visions on or off."] = "Включает или выключает все Visions."
L["Breath Bar"] = "Полоса дыхания"
L["The breath bar and the game's other bars like it."] = "Полоса дыхания и другие похожие полосы игры."
