L["Your own roll always shows on an item's panel."] = "Ваш бросок всегда виден на панели предмета."
L["Always show rolls I need"] = "Всегда броски, где я «Нужно»"
L["Items you roll Need on always show everyone's rolls."] = "Предметы, на которые вы выбрали «Нужно», всегда показывают броски всех."
L["Shows the extra lines under an item's players, like who passed, in a party, raid or both."] = "Показывает доп. строки под игроками предмета, например кто отказался, в группе, рейде или в обоих."
L["Show selected count"] = "Число выбравших"
L["Stays hidden while another addon handles loot rolls."] = "Остается скрытым, пока розыгрышем занимается другой аддон."
L["In CineMode, shows the nameplates of players dueling near you so you can watch."] = "В CineMode показывает индикаторы дуэлянтов рядом, чтобы вы могли смотреть."
L["Shows an icon beside a duelist's nameplate while they're crowd controlled."] = "Показывает значок рядом с индикатором дуэлянта, пока он под контролем."
L["Instant spells"] = "Мгновенные заклинания"
L["Shows a duelist's instant spells as icons beside their nameplate."] = "Показывает мгновенные заклинания дуэлянта значками рядом с его индикатором."
L["Spell names"] = "Названия заклинаний"
L["The newest instant spell's name shows above its icon."] = "Название последнего мгновенного заклинания видно над его значком."
L["Hides other players' duels while you're in one."] = "Скрывает чужие дуэли, пока вы сами в дуэли."
L["Shows a 30-second pretend duel between nearby players so you can see how it looks."] = "Показывает 30-секундную пробную дуэль между игроками рядом, чтобы увидеть, как это выглядит."
