L["A healer shows once their health drops below this."] = "Лекарь показывается, когда его здоровье ниже этого."
L["How much of a hidden healer still shows."] = "Насколько виден скрытый лекарь."
L["A damage dealer shows once their health drops below this."] = "Боец показывается, когда его здоровье ниже этого."
L["How much of a hidden damage dealer and the group titles still show."] = "Насколько видны скрытый боец и названия групп."
L["A pet shows once its health drops below this."] = "Питомец показывается, когда его здоровье ниже этого."
