L["Show only while hurt"] = "Только при ранении"
L["A friendly player's name shows once they're hurt; the rest of their plate stays as it is."] = "Имя дружественного игрока показывается, когда он ранен; остальной индикатор как был."
L["The whole plate shows once they're hurt, as your nameplate style has it."] = "Когда игрок ранен, весь индикатор показывается в вашем стиле индикаторов."
L["A group member's plate shows once their health drops below this."] = "Индикатор участника группы показывается, когда его здоровье ниже этого."
L["How much of a hidden group member's plate still shows."] = "Насколько виден скрытый индикатор участника группы."
L["Other players"] = "Другие игроки"
L["Another player's plate shows once their health drops below this."] = "Индикатор другого игрока показывается, когда его здоровье ниже этого."
L["How much of a hidden player's plate still shows."] = "Насколько виден скрытый индикатор игрока."
L["A pet's or minion's plate shows once its health drops below this."] = "Индикатор питомца или прислужника показывается, когда его здоровье ниже этого."
L["How much of a hidden pet's plate still shows."] = "Насколько виден скрытый индикатор питомца."
L["Hold your Show hidden tooltips key to see a hidden tooltip in CineMode."] = "Удерживайте клавишу «Показать скрытые подсказки», чтобы увидеть скрытую подсказку в CineMode."
