L["Quest objective mobs"] = "Существа для заданий"
L["These tooltips show the After column's parts right away."] = "Эти подсказки сразу показывают части столбца «После»."
L["No wait for"] = "Без ожидания для"
L["Filtered tooltips"] = "Фильтруемые подсказки"
L["Tooltips with these names never show in CineMode."] = "Подсказки с этими названиями никогда не видны в CineMode."
